        if(!$test&&!isset($in['accessKey'])&&!isset($in['email']))throw new HttpError(400,'Nhập khóa hoặc email tra cứu.');if($test&&!preg_match('/^J[GMC][A-F0-9]{10}$/D',$in['code']))throw new HttpError(400,'TEST chỉ dùng vé đơn hoặc giỏ WEB.');
