        $id=$object->id??null;if(is_float($id)&&is_finite($id)&&floor($id)===$id&&$id>0&&$id<=9007199254740991)$id=(int)$id;if(is_int($id)&&($id<=0||$id>9007199254740991)||!is_int($id)&&(!is_string($id)||!preg_match('/^[0-9]{1,30}$/D',$id)))throw new HttpError(400,'Invalid transaction ID');$p['id']=ltrim((string)$id,'0');if($p['id']==='')throw new HttpError(400,'Invalid transaction ID');
