    public function webhook(string $raw,string $authorization,string $timestamp='',string $signature=''):array
    {
        if($raw===''||strlen($raw)>1048576)throw new HttpError(413,'Webhook body too large or empty');$settings=new PaymentSettings($this->db,$this->env);$c=$settings->config();$credential=SepaySettings::credential($c);if(!$credential)throw new HttpError(401,'Webhook authentication failed');$cipher=new SecretCipher(OrderMail::directory());$secret=$cipher->decrypt($credential);$ok=$c['sepayAuth']==='HMAC_SHA256'?self::verifyHmac($raw,$timestamp,$signature,$secret):hash_equals('Apikey '.$secret,$authorization);if(!$ok)throw new HttpError(401,'Webhook authentication failed');$p=self::payload($raw);
