            preg_match_all('/\bJM[PR][A-F0-9]{24}\b/',strtoupper($p['content']),$matches);$tokens=array_values(array_unique($matches[0]));$fingerprint=hash('sha256',json_encode(['id'=>$p['id'],'tokens'=>$tokens,'amount'=>$p['transferAmount'],'bank'=>strtolower($p['gateway']),'account'=>$p['accountNumber'],'sub'=>$p['subAccount']??''],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$prior=$this->query('SELECT fingerprint FROM jingo_gateway_events WHERE id=?',[$id])->fetchColumn();if($prior!==false){if(!hash_equals($prior,$fingerprint))throw new HttpError(409,'Giao dịch đã nhận với dữ liệu khác.');return ['success'=>true];}
            $reason=count($tokens)===1?'':(count($tokens)>1?'Nội dung có nhiều mã thanh toán.':'Không có mã yêu cầu thanh toán JMP.');if(!empty($p['code'])&&preg_match('/^JM[PR][A-F0-9]{24}$/iD',$p['code'])&&(count($tokens)!==1||strtoupper($p['code'])!==$tokens[0]))$reason='Mã thanh toán SePay không khớp nội dung.';if($p['accountNumber']!==$c['accountNumber']||strcasecmp($p['gateway'],$c['bankCode'])!==0||($p['subAccount']??'')!=='')$reason='Tài khoản/ngân hàng nhận không khớp hoặc tài khoản ảo chưa hỗ trợ.';
