                if($a['mode']!==$c['mode'])$reason='Môi trường giao dịch không khớp.';if((int)$a['amount']!==$p['transferAmount'])$reason='Số tiền không khớp.';if(strtotime($a['expires_at'].' UTC')<=time())$reason='Yêu cầu đã hết hạn; cần đối soát.';if(($snapshot['bankCode']??null)!==$current['bankCode']||($snapshot['accountNumber']??null)!==$current['accountNumber'])$reason='Tài khoản nhận đã thay đổi.';
                try{$targets=new PaymentTargets($this->db);if(isset($snapshot['hotelId']))$code=$this->query('SELECT code FROM jingo_stay_bookings WHERE id=?',[$snapshot['hotelId']])->fetchColumn();elseif(isset($snapshot['bundleId']))$code=$this->query('SELECT code FROM jingo_checkout_bundles WHERE id=?',[$snapshot['bundleId']])->fetchColumn();elseif(isset($snapshot['cartId']))$code=$this->query('SELECT code FROM jingo_carts WHERE id=?',[$snapshot['cartId']])->fetchColumn();else $code=$this->query('SELECT code FROM jingo_orders WHERE id=?',[$a['order_id']])->fetchColumn();if(!$code)throw new HttpError(409,'Đơn không còn hợp lệ.');$s=$targets->state($code);if($s['amount']!==$p['transferAmount'])$reason='Số tiền đơn không khớp.';if(isset($snapshot['cartId'])&&array_map(fn($o)=>['id'=>$o['id'],'amount'=>json_decode($o['snapshot'],true,512,JSON_THROW_ON_ERROR)['total']],$s['orders'])!==$snapshot['cartOrders'])$reason='Thành phần giỏ đã thay đổi.';}catch(HttpError $e){$reason=$reason?:$e->getMessage();}
